import React,{createContext,useContext,useEffect,useMemo,useRef,useState} from 'react';
import {createRoot} from 'react-dom/client';
import {AssistantRuntimeProvider,useExternalStoreRuntime,ThreadPrimitive,MessagePrimitive,type TextMessagePartProps} from '@assistant-ui/react';
import Markdown,{type Components} from 'react-markdown';
import remarkGfm from 'remark-gfm';
import remarkMath from 'remark-math';
import rehypeKatex from 'rehype-katex';
import 'katex/dist/katex.min.css';
import {artifactDocument,validArtifactEvent} from './artifact';
import './style.css';
import {normalizeMath,inlineComparisonTex} from './math';
import {CourseStudio} from './course-studio';
import {MaterialsLibrary} from './materials-library';
import {AttemptFeedback,friendlyReviewError,type ReviewProgress} from './attempt-feedback';
import {preserveParagraphIndentation} from './markdown';
import {AccessibleMath,formulaTex,MathReadingProvider,MathReadingSettings} from './math-accessibility';

type Activity={id:string,version:number,spec:any,state:Record<string,any>,created?:string};
type View={curriculum?:any,learning?:any,session:any,activities:Activity[],messages:any[],attempts:any[],progress:any[],recommendation?:any};
async function api(url:string,body?:any){const response=await fetch('/api'+url,{method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});const data=await response.json();if(!response.ok)throw Error(data.error??'Operazione non riuscita.');return data;}
const ResumeExplanation=createContext<(id:string)=>void>(()=>{});
const Reviews=createContext<Record<string,ReviewProgress>>({});
const Tutor=createContext<()=>void>(()=>{});
const Sources=createContext<(id:string)=>void>(()=>{});
// Stable component types preserve formula state when course polling rerenders prose.
// Inline component functions remount AccessibleMath and briefly restore raw TeX.
const proseComponents:Components={
  code:({node,children,className,...props})=>{const tex=!className&&typeof children==='string'?inlineComparisonTex(children):'';const code=<code className={className} {...props}>{children}</code>;return tex?<AccessibleMath tex={tex}>{code}</AccessibleMath>:code;},
  span:({node,className,children,...props})=>className?.split(' ').includes('katex')?<AccessibleMath tex={formulaTex(node)}><span className={className} {...props}>{children}</span></AccessibleMath>:<span className={className} {...props}>{children}</span>,
  a:function ProseLink({href,children}){const open=useContext(Sources);return href?.startsWith('source:')?<button className="source-link" onClick={()=>open(href.slice(7))}>{children}</button>:<a href={href} target="_blank" rel="noreferrer">{children}</a>;},
};
function Prose({text}:{text:string}){return <Markdown remarkPlugins={[remarkGfm,remarkMath]} rehypePlugins={[preserveParagraphIndentation,rehypeKatex]} urlTransform={url=>/^(source:|https?:|#)/.test(url)?url:''} components={proseComponents}>{normalizeMath(text)}</Markdown>;}
const ActivityRendering=createContext<(id:string,version:number)=>React.ReactNode>(()=>null);
function StudyTool({args}:any){const render=useContext(ActivityRendering);return render(args.id,args.version);}
const Text=({text}:TextMessagePartProps)=><Prose text={text}/>;
function AssistantMessage(){return <MessagePrimitive.Root className="message assistant"><span className="speaker">TUTOR</span><MessagePrimitive.Content components={{Text,tools:{by_name:{study_activity:StudyTool}}}}/></MessagePrimitive.Root>;}
function UserMessage(){return <MessagePrimitive.Root className="message user"><span className="speaker">TU</span><MessagePrimitive.Content components={{Text,tools:{by_name:{study_activity:StudyTool}}}}/></MessagePrimitive.Root>;}

function HtmlActivity({activity,onEvent}:{activity:Activity,onEvent:(kind:string,payload:any)=>Promise<any>}){
  const frame=useRef<HTMLIFrameElement>(null),[error,setError]=useState('');
  const token=useMemo(()=>crypto.randomUUID(),[activity.id,activity.version]);
  const document=useMemo(()=>artifactDocument(activity.spec.html??'',token),[activity.id,activity.version,activity.spec.html,token]);
  const callback=useRef(onEvent);callback.current=onEvent;
  const state=useRef(activity.state);state.current=activity.state;
  useEffect(()=>{const receive=(event:MessageEvent)=>{if(!validArtifactEvent(event,frame.current?.contentWindow??null,token))return;const {kind,payload,id}=event.data;if(kind==='render_error'){setError('La visualizzazione ha un problema. La versione testuale è disponibile qui sotto.');return;}void callback.current(kind,payload).then(result=>frame.current?.contentWindow?.postMessage({channel:'polimi-ack',token,id,ok:result!==null,result},'*'));};window.addEventListener('message',receive);return()=>window.removeEventListener('message',receive);},[token]);
  useEffect(()=>{const sync=()=>frame.current?.contentWindow?.postMessage({channel:'polimi-theme',token,theme:window.document.documentElement.dataset.theme},'*');sync();const observer=new MutationObserver(sync);observer.observe(window.document.documentElement,{attributes:true,attributeFilter:['data-theme']});return()=>observer.disconnect();},[token]);
  return <><iframe ref={frame} className="artifact" title={activity.spec.title} sandbox="allow-scripts" srcDoc={document} onLoad={()=>{frame.current?.contentWindow?.postMessage({channel:'polimi-restore',token,state:state.current},'*');frame.current?.contentWindow?.postMessage({channel:'polimi-theme',token,theme:window.document.documentElement.dataset.theme},'*');}}/>{error&&<p role="alert">{error}</p>}<details open={!!error}><summary>Versione testuale</summary><Prose text={activity.spec.fallback??'Usa il campo di risposta per descrivere il tuo ragionamento al tutor.'}/></details></>;
}

function ActivityCard({activity,view,onEvent,onNext,busy,expanded,setExpanded,onAssess,onCorrect}:{activity:Activity,view:View,onEvent:(kind:string,payload:any)=>Promise<any>,onNext:()=>void,busy:boolean,expanded:boolean,setExpanded:(v:boolean)=>void,onAssess:(id:string)=>void,onCorrect:(id:string,text:string)=>void}){
  const requestTutor=useContext(Tutor),reviews=useContext(Reviews),resumeExplanation=useContext(ResumeExplanation);
  const aid=activity.id,version=activity.version,storageKey=`studio-draft:${view.session.id}:${aid}:${version}`;
  const [answer,setAnswer]=useState(()=>localStorage.getItem(storageKey)??String(activity.state.answer??''));
  const [feedback,setFeedback]=useState(''),[correction,setCorrection]=useState(''),[sending,setSending]=useState(false),[actionKind,setActionKind]=useState('');const submitting=useRef(false);
  const timeout=useRef<ReturnType<typeof setTimeout>|null>(null),latest=useRef(answer),edited=useRef(false);
  const onEventRef=useRef(onEvent);onEventRef.current=onEvent;
  const spec=activity.spec,exam=view.session.mode==='exam'||!!activity.spec.curriculum?.recall;
  const attempts=view.attempts.filter(a=>a.activity===aid&&a.version===version),attempt=attempts.at(-1);
  useEffect(()=>{if(!edited.current&&localStorage.getItem(storageKey)===null){const restored=String(activity.state.answer??'');setAnswer(restored);latest.current=restored;}},[storageKey,activity.state.answer]);
  function change(value:string){edited.current=true;setAnswer(value);latest.current=value;localStorage.setItem(storageKey,value);if(timeout.current)clearTimeout(timeout.current);timeout.current=setTimeout(()=>{timeout.current=null;void onEventRef.current('change',{answer:value});},250);}
  useEffect(()=>()=>{if(timeout.current){clearTimeout(timeout.current);void onEventRef.current('change',{answer:latest.current});}},[]);
  function flushDraft(){if(timeout.current){clearTimeout(timeout.current);timeout.current=null;void onEventRef.current('change',{answer:latest.current});}}
  useEffect(()=>{window.addEventListener('studio-flush-drafts',flushDraft);return()=>window.removeEventListener('studio-flush-drafts',flushDraft);},[]);
  async function action(kind:string){if(submitting.current)return;if(['hint','explain','solution'].includes(kind))requestTutor();submitting.current=true;setSending(true);setActionKind(kind);try{if(timeout.current){clearTimeout(timeout.current);timeout.current=null;}const result=await onEvent(kind,{answer});if(result?.feedback)setFeedback(result.feedback);}finally{submitting.current=false;setSending(false);}}
  return <section className={'activity-card '+(expanded?'expanded':'')} data-activity-id={aid} aria-labelledby={'activity-title-'+aid+'-'+version}>
    <header className="activity-header"><span className="eyebrow">{exam?'PROVA AUTONOMA':spec.kind==='html'?'ESPLORA':'IL PROSSIMO PASSO'}</span><button className="icon-button" onClick={()=>setExpanded(!expanded)} aria-label={expanded?'Riduci attività':'Espandi attività'}>{expanded?'↙':'↗'}</button></header>
    <h2 id={'activity-title-'+aid+'-'+version}>{spec.title}</h2><div className="activity-prompt"><Prose text={spec.prompt??''}/></div>
    {spec.origin&&<span className="tag">{{generated:'Esercizio generato dal tutor',adapted:'Variante di un esercizio del corso',authentic:'Quesito tratto da un tema d’esame'}[spec.origin as string]??spec.origin}</span>}{spec.assumptions&&<p className="quiet">Ipotesi: {spec.assumptions}</p>}{spec.model&&<p className="quiet">Modello rappresentato: {spec.model}</p>}
    {spec.authentic&&<span className="tag">Domanda da un tema originale · criteri proposti</span>}
    {spec.kind==='html'&&<HtmlActivity activity={activity} onEvent={onEvent}/>}
    {spec.kind!=='explain'&&spec.kind!=='html'&&<form onSubmit={e=>{e.preventDefault();void action('submit');}}>
      {spec.kind==='choice'?<fieldset><legend>La tua risposta</legend>{spec.options?.map((option:string)=><label className={'choice '+(answer===option?'selected':'')} key={option}><input type="radio" name={aid} value={option} checked={answer===option} onChange={()=>change(option)}/><span>{option}</span></label>)}</fieldset>:<label className="answer-label">La tua risposta{spec.kind==='numeric'?<input aria-label="La tua risposta" inputMode="decimal" value={answer} onChange={e=>change(e.target.value)} onBlur={flushDraft} placeholder="Scrivi il risultato"/>:<textarea aria-label="La tua risposta" rows={spec.kind==='completion'?3:7} value={answer} onChange={e=>change(e.target.value)} onBlur={flushDraft} placeholder={spec.kind==='completion'?'Completa l’espressione…':'Scrivi il ragionamento, le ipotesi e la conclusione…'}/>}</label>}
      <div className="action-row"><button className="primary" type="submit" disabled={busy||sending||!answer.trim()}>{sending&&actionKind==='submit'?'Salvo la risposta…':exam?'Consegna':'Verifica risposta'}</button><span className="quiet">Bozza salvata automaticamente</span></div>
    </form>}
    {attempt&&<AttemptFeedback attempt={attempt} review={reviews[attempt.id]} busy={busy} onAssess={()=>onAssess(attempt.id)} onOpenTutor={requestTutor} onResumeExplanation={()=>resumeExplanation(attempt.id)} renderProse={text=><Prose text={text}/>}>{attempt.source_session&&<p className="quiet">Risposta e valutazione conservate da una conversazione precedente.</p>}<details><summary>Risposta di questo tentativo</summary><Prose text={typeof attempt.answer==='string'?attempt.answer:JSON.stringify(attempt.answer)??''}/></details><details><summary>Criteri e contestazione</summary><Prose text={attempt.grade.rubric??spec.rubric??''}/>{attempt.correction?<p>La tua correzione: {attempt.correction}</p>:<><label>Descrivi cosa va corretto<textarea value={correction} onChange={e=>setCorrection(e.target.value)} rows={2}/></label><button disabled={!correction.trim()} onClick={()=>onCorrect(attempt.id,correction)}>Salva contestazione</button></>}</details></AttemptFeedback>}
    {!exam&&<div className="help-row"><button disabled={busy||sending} onClick={()=>void action('hint')}>Un indizio</button><button disabled={busy||sending} onClick={()=>void action('explain')}>Spiegamelo</button><button disabled={busy||sending} onClick={()=>void action('solution')}>Mostra la soluzione</button></div>}
    {feedback&&<div className="feedback"><Prose text={feedback}/></div>}
    {!exam&&<button className={spec.kind==='explain'||spec.kind==='html'?'primary':'next'} onClick={onNext} disabled={busy}>{spec.kind==='explain'?'Continua':spec.kind==='html'?'Metti alla prova quello che hai osservato':'Passa al prossimo passo →'}</button>}
    {!!spec.sources?.length&&<SourceButtons ids={spec.sources}/>}
  </section>;
}

function SourceButtons({ids}:{ids:string[]}){const open=useContext(Sources);return <div className="source-row"><span>Fonti collegate</span>{ids.map((id,i)=><button key={id} onClick={()=>open(id)}>↗ {i+1}</button>)}</div>;}

function SourcePanel({source,sid,onClose,embedded=false}:{source:any,sid:string,onClose:()=>void,embedded?:boolean}){
  const open=useContext(Sources);const video=useRef<HTMLVideoElement>(null);const media=`/api/sessions/${sid}/media/${encodeURIComponent(source.id)}`;
  return <aside className={'source-panel'+(embedded?' source-embedded':'')} aria-label="Fonte originale"><header><div><span className="eyebrow">FONTE ORIGINALE</span><h2>{source.title}</h2></div><button onClick={onClose} aria-label="Chiudi fonte">×</button></header><p className="quiet">{source.kind==='notebook'?`Cella ${source.page}`:source.page?`Pagina ${source.page}`:''} · {source.quality}</p>{source.metadata?.issue&&<p className="notice">{source.metadata.issue}</p>}{source.kind==='pdf'?<div className="pdf-page"><a href={`${media}#page=${source.page}`} target="_blank" rel="noreferrer">Apri il PDF originale · pagina {source.page} ↗</a><img alt={`Pagina ${source.page} del PDF originale`} src={`/api/sessions/${sid}/page/${encodeURIComponent(source.id)}`}/></div>:['video','alignment'].includes(source.kind)?<video ref={video} controls preload="metadata" src={media} onLoadedMetadata={()=>{if(video.current)video.current.currentTime=source.start??0;}}/>:null}<details open={source.kind!=='pdf'}><summary>Passaggio indicizzato</summary><pre>{source.text}</pre></details>{!!source.context?.length&&<details><summary>Contesto vicino</summary>{source.context.map((passage:any)=><div key={passage.id}><button onClick={()=>open(passage.id)}>Apri {passage.page!=null?'pagina/cella '+passage.page:'passaggio a '+Math.round(passage.start)+' s'} ↗</button><pre>{passage.text}</pre></div>)}</details>}{source.metadata?.alignment&&<details><summary>Associazione alle slide / celle</summary><pre>{JSON.stringify({status:source.metadata.alignment.status,confidence:source.metadata.alignment.confidence,material:source.metadata.alignment.material,candidates:source.metadata.alignment.candidates},null,2)}</pre></details>}</aside>;
}

function ModelPanel({onClose,onSaved}:{onClose:()=>void,onSaved:()=>void}){
  const [routingSaving,setRoutingSaving]=useState(false);
  const [catalog,setCatalog]=useState<any>(null),[selection,setSelection]=useState(''),[error,setError]=useState(''),[login,setLogin]=useState<any>(null),[value,setValue]=useState('');
  async function load(){try{const c=await api('/models');setCatalog(c);setSelection(c.models.length?JSON.stringify(c.models.find((m:any)=>m.provider===c.selected?.provider&&m.id===c.selected?.id)??c.models[0]):'');}catch(e:any){setError(e.message);}}
  useEffect(()=>{void load();const previous=document.activeElement as HTMLElement;const dialog=document.querySelector('[role=dialog]') as HTMLElement;const first=()=>dialog?.querySelector<HTMLElement>('button,input,select,textarea,a[href]');first()?.focus();const trap=(event:KeyboardEvent)=>{if(event.key==='Escape'){onClose();return;}if(event.key!=='Tab')return;const items=[...dialog.querySelectorAll<HTMLElement>('button:not(:disabled),input,select,textarea,a[href]')];const start=items[0],end=items.at(-1);if(event.shiftKey&&document.activeElement===start){event.preventDefault();end?.focus();}else if(!event.shiftKey&&document.activeElement===end){event.preventDefault();start?.focus();}};document.addEventListener('keydown',trap);return()=>{document.removeEventListener('keydown',trap);previous?.focus();};},[]);
  useEffect(()=>{if(!login?.id||login.status==='done'||login.status==='error')return;const timer=setInterval(()=>{void api('/login/'+login.id).then(data=>{setLogin({id:login.id,...data});if(data.status==='done'){void load();onSaved();}if(data.error)setError(data.error);}).catch(e=>setError(e.message));},1000);return()=>clearInterval(timer);},[login?.id,login?.status]);
  return <div className="modal-backdrop"><section className="modal" role="dialog" aria-modal="true" aria-label="Modello e accesso"><header><h2>Modello e accesso</h2><button onClick={onClose} aria-label="Chiudi impostazioni">×</button></header><p>Usa i provider di Pi. I passaggi pertinenti e le tue risposte vengono inviati al modello selezionato.</p>{error&&<p role="alert" className="notice">{error}</p>}{catalog?<><label>Modello disponibile<select value={selection} onChange={e=>setSelection(e.target.value)}>{catalog.models.map((m:any)=><option key={m.provider+'/'+m.id} value={JSON.stringify(m)}>{m.provider} · {m.name}</option>)}</select></label>{!catalog.models.length&&<p>Nessun provider autenticato. Completa un accesso qui sotto.</p>}<button className="primary" disabled={!selection} onClick={()=>void api('/model',JSON.parse(selection)).then(()=>{onSaved();onClose();}).catch(e=>setError(e.message))}>Usa questo modello</button><label className="course-check"><input type="checkbox" checked={catalog.routing?.enabled===true} disabled={routingSaving||(catalog.selected?.provider!=='openai'&&!catalog.routing?.enabled)} onChange={e=>{const enabled=e.target.checked;setRoutingSaving(true);setError('');void api('/model-routing',{enabled}).then(result=>{setCatalog((old:any)=>({...old,routing:result.routing}));onSaved();}).catch(e=>setError(e.message)).finally(()=>setRoutingSaving(false));}}/>Assegnazione automatica Luna/Sol</label>{routingSaving&&<p role="status">Salvo l’assegnazione dei modelli…</p>}<p className="quiet">Con un provider OpenAI: Luna seleziona gli intervalli; Sol verifica solo le esclusioni e gestisce lettura tecnica, dubbi, piano, spiegazioni, chat e revisioni. Le fonti incerte restano incluse. Vale dai prossimi compiti; non rianalizza quelli già completati. Disattiva per usare soltanto il modello selezionato.</p>{catalog.providers.some((p:any)=>p.id==='openai'&&p.oauth)&&<div className="provider"><div><strong>Il tuo abbonamento ChatGPT</strong><p className="quiet">Accedi nel browser con il tuo account; poi scegli uno dei modelli disponibili. La chiave API è una modalità separata.</p></div><button className="primary" disabled={login?.status==='pending'||!!login?.id&&!login.status} onClick={()=>void api('/login',{provider:'openai',type:'oauth'}).then(setLogin).catch(e=>setError(e.message))}>Collega ChatGPT</button></div>}<details><summary>Altri accessi e chiavi API</summary>{catalog.providers.filter((p:any)=>p.oauth||p.apiKey).map((p:any)=><div className="provider" key={p.id}><span>{p.name??p.id}</span>{p.oauth&&<button onClick={()=>void api('/login',{provider:p.id,type:'oauth'}).then(setLogin).catch(e=>setError(e.message))}>{p.loginLabel??'Accedi'}</button>}{p.apiKey&&<button onClick={()=>void api('/login',{provider:p.id,type:'api_key'}).then(setLogin).catch(e=>setError(e.message))}>Chiave API</button>}</div>)}</details></>:<p role="status">Verifico i provider…</p>}{login&&<div className="login-status">{login.events?.map((event:any,i:number)=><div key={i}>{event.message||event.instructions||event.userCode}{event.url&&<a href={event.url} target="_blank" rel="noreferrer">Apri accesso</a>}{event.verificationUri&&<a href={event.verificationUri} target="_blank" rel="noreferrer">Conferma codice</a>}{event.links?.map((link:any)=><a key={link.url} href={link.url} target="_blank" rel="noreferrer">{link.label??'Continua'}</a>)}</div>)}{login.prompt&&<form onSubmit={e=>{e.preventDefault();void api('/login/'+login.id,{value}).then(()=>setValue('')).catch(e=>setError(e.message));}}><label>{login.prompt.message}{login.prompt.type==='select'?<select value={value} onChange={e=>setValue(e.target.value)}><option value="">Scegli…</option>{login.prompt.options.map((o:any)=><option key={o.id} value={o.id}>{o.label}</option>)}</select>:<input type={login.prompt.type==='secret'?'password':'text'} value={value} onChange={e=>setValue(e.target.value)} autoComplete="off"/>}</label><button type="submit">Continua accesso</button></form>}{login.status==='done'&&<p>Accesso completato.</p>}</div>}</section></div>;
}

function IndexStatus({course}:{course:string}){
  const [job,setJob]=useState<any>(null);
  useEffect(()=>{let active=true;const load=()=>void api('/embeddings').then(j=>{if(active)setJob(j[course]);}).catch(()=>{});load();const timer=setInterval(load,3000);return()=>{active=false;clearInterval(timer);};},[course]);
  if(!job)return null;
  return <p className="quiet" role="status">{job.error?'Ricerca testuale disponibile. Embeddings: '+job.error:job.running?`Preparo la ricerca semantica locale: ${Math.max(0,job.total-job.pending)} / ${job.total||'…'} passaggi. Puoi continuare a studiare.`:'Ricerca semantica e testuale disponibili · indice locale aggiornato.'}</p>;
}

function SessionHistory({course,onResume,busy}:{course:string,onResume:(sid:string)=>void,busy:boolean}){
  const [sessions,setSessions]=useState<any[]>([]),[query,setQuery]=useState(''),[error,setError]=useState(''),[offset,setOffset]=useState(0);
  async function load(page=0){try{const rows=await api('/history?course='+encodeURIComponent(course)+'&q='+encodeURIComponent(query)+'&offset='+page);setSessions(rows);setOffset(page);setError('');}catch(e:any){setError(e.message);}}
  useEffect(()=>{void load();},[course]);
  return <section className="overview"><span className="eyebrow">IL FILO DELLO STUDIO</span><h1>Le tue sessioni</h1><p>Conversazioni, attività, bozze e tentativi vengono conservati. Puoi chiedere al tutor di recuperarli.</p><form className="search" onSubmit={e=>{e.preventDefault();void load();}}><label className="sr-only" htmlFor="session-query">Cerca nelle sessioni</label><input id="session-query" value={query} onChange={e=>setQuery(e.target.value)} placeholder="Un argomento o una frase della conversazione…"/><button>Cerca sessioni</button></form>{error&&<p role="alert">{error}</p>}{sessions.map(s=><article className="concept" key={s.id}><div><h3>{s.goal}</h3><p>{new Date(s.updated).toLocaleString('it-IT')} · {s.mode==='exam'?'Simulazione':'Studio'} · {s.messages} messaggi</p></div><button disabled={busy} onClick={()=>onResume(s.id)}>Riprendi sessione</button></article>)}{!sessions.length&&<p>Nessuna sessione trovata.</p>}<div className="session-links"><button disabled={offset===0} onClick={()=>void load(Math.max(0,offset-30))}>Precedenti</button><button disabled={sessions.length<30} onClick={()=>void load(offset+30)}>Altre sessioni</button></div></section>;
}

function ThemeToggle(){
  const [theme,setTheme]=useState(()=>document.documentElement.dataset.theme??'light');
  useEffect(()=>{const media=matchMedia('(prefers-color-scheme: dark)');const sync=()=>{try{if(localStorage.getItem('studio-theme'))return;}catch{}const next=media.matches?'dark':'light';document.documentElement.dataset.theme=next;setTheme(next);};const storage=(event:StorageEvent)=>{if(event.key!=='studio-theme')return;const next=event.newValue==='dark'||event.newValue==='light'?event.newValue:media.matches?'dark':'light';document.documentElement.dataset.theme=next;setTheme(next);};media.addEventListener('change',sync);window.addEventListener('storage',storage);return()=>{media.removeEventListener('change',sync);window.removeEventListener('storage',storage);};},[]);
  return <button className="theme-toggle" aria-label="Modalità scura" aria-pressed={theme==='dark'} onClick={()=>{const next=theme==='dark'?'light':'dark';document.documentElement.dataset.theme=next;setTheme(next);try{localStorage.setItem('studio-theme',next);}catch{}}}><span aria-hidden="true">{theme==='dark'?'☀':'☾'}</span> {theme==='dark'?'Tema chiaro':'Tema scuro'}</button>;
}

function App(){
  const [boot,setBoot]=useState<any>(null),[course,setCourse]=useState(''),[view,setView]=useState<View|null>(null),[tab,setTab]=useState(()=>{const saved=localStorage.getItem('studio-last-view');return ['corso','percorso','allenamento','fonti','studio'].includes(saved??'')?saved!:'corso';}),[source,setSource]=useState<any>(null),[error,setError]=useState(''),[status,setStatus]=useState(''),[busy,setBusy]=useState(false),[draft,setDraft]=useState(''),[stream,setStream]=useState(''),[models,setModels]=useState(false),[expanded,setExpanded]=useState(false),[minutes,setMinutes]=useState(25),[goal,setGoal]=useState('Capire e saper risolvere'),[query,setQuery]=useState(''),[results,setResults]=useState<any[]>([]);
  useEffect(()=>{if(['corso','percorso','allenamento','fonti'].includes(tab))localStorage.setItem('studio-last-view',tab);},[tab]);
  const [reviews,setReviews]=useState<Record<string,ReviewProgress>>({});
  const [tutorRequest,setTutorRequest]=useState(0),[sourceRequest,setSourceRequest]=useState(0),[navigationEpoch,setNavigationEpoch]=useState(0);
  const inCourse=['corso','percorso','allenamento'].includes(tab);
  const saving=useRef<Promise<any>>(Promise.resolve()),viewRef=useRef(view);viewRef.current=view;
  async function bootstrap(){const data=await api('/bootstrap');setBoot(data);setCourse(c=>c||data.selected||'');}
  useEffect(()=>{void bootstrap().catch(e=>setError(e.message));},[]);
  async function work(run:()=>Promise<void>,onError?:(message:string)=>void){setError('');setBusy(true);try{await run();}catch(e:any){setError(e.message);onError?.(e.message);}finally{setBusy(false);setStatus('');}}
  async function open(mode='learn',fresh=false){await work(async()=>{await saving.current;setStatus('Preparo le fonti del corso…');await api('/import',{course});setView(await api('/sessions',{course,goal,minutes,mode,fresh}));setTab('studio');setSource(null);setExpanded(false);});}
  async function startBasics(){let sid:string|undefined;await work(async()=>{await saving.current;setStatus('Preparo il percorso dalle tue lezioni…');await api('/import',{course});const next=await api('/sessions',{course,goal,minutes,mode:'learn',fresh:true,approach:'beginner'});sid=next.session.id;setView(next);setTab('studio');setSource(null);setExpanded(false);});if(sid)await chat('Parti da zero seguendo i concetti spiegati nella prima lezione e i materiali del mio corso. Prepara il piano dalle fonti e comincia con i prerequisiti del primo argomento, senza dare nulla per scontato.',sid);}
  async function beginnerAction(action:string,data:any={}){if(!view)return;const sid=view.session.id;let done=false;await work(async()=>{await saving.current;setView(await api(`/sessions/${sid}/beginner/${action}`,data));setSource(null);setExpanded(false);setTab('studio');done=true;});if(done)await chat(action==='recall'?'Proponi una verifica differita dell’argomento selezionato senza anticipare spiegazioni o soluzioni.':'Continua dalla fase corrente del percorso dalle basi. Segui le fonti della lezione scelta e adatta la spiegazione ai miei tentativi.',sid);}
  async function refresh(sid:string){const next=await api('/sessions/'+sid);setView(next);}
  useEffect(()=>{if(tab==='fonti'&&course&&!view)void api('/sessions',{course,minutes,goal,mode:'learn',fresh:false}).then(setView).catch(e=>setError(e.message));},[tab,course]);
  const recommendation=view?.recommendation??(boot?.selected===course?boot?.recommendation:null);
  const [courseExpanded,setCourseExpanded]=useState<string|null>(null);
  useEffect(()=>{if(!courseExpanded)return;const close=(e:KeyboardEvent)=>{if(e.key==='Escape')setCourseExpanded(null);};window.addEventListener('keydown',close);return()=>window.removeEventListener('keydown',close);},[courseExpanded]);
  const current=view?[...view.activities].reverse().find(a=>a.id===view.session.current&&(!view.session.current_version||a.version===view.session.current_version)):undefined;
  useEffect(()=>{if(view){setDraft(sessionStorage.getItem('studio-chat:'+view.session.id)??sessionStorage.getItem('studio-chat-pending:'+view.session.id)??'');setMinutes(view.session.minutes);setGoal(view.session.goal);}},[view?.session.id]);
  async function sendEventFor(activity:Activity,kind:string,payload:any,sessionId?:string){
    const sid=sessionId??viewRef.current?.session.id;if(!sid)return;
    const event={aid:activity.id,version:activity.version,event_id:crypto.randomUUID(),kind,payload};
    let acknowledged=false,submittedAttempt:string|undefined;
    const localKey=`studio-pending:${sid}:${event.event_id}`;localStorage.setItem(localKey,JSON.stringify(event));
    const action=async()=>{const result=await api(`/sessions/${sid}/events`,event);acknowledged=true;if(kind==='submit')submittedAttempt=result.attempt?.id;localStorage.removeItem(localKey);if(kind==='submit'&&result.attempt&&!result.duplicate&&inCourse)setReviews(current=>({...current,[result.attempt.id]:{status:'pending'}}));if(kind==='change'||kind==='try'||kind==='reset'){setView(v=>v && v.session.id===sid?{...v,activities:v.activities.map(a=>a.id===activity.id&&a.version===activity.version?{...a,state:kind==='reset'?{}:{...a.state,...payload}}:a)}:v);}else if(viewRef.current?.session.id===sid)await refresh(sid);return result;};
    const promise=saving.current.catch(()=>{}).then(action);saving.current=promise;
    try{const result=await promise;if(result?.feedback?.startsWith('Chiedi al tutor')&&['hint','explain','solution'].includes(kind))void chat((kind==='hint'?'Dammi un indizio':kind==='solution'?'Mostra la soluzione':'Spiegami il concetto')+' per l’attività '+activity.spec.title+'. Usa le fonti collegate.');return result;}catch(e:any){if(submittedAttempt)setReviews(current=>({...current,[submittedAttempt!]:{status:'error',error:'Non è stato possibile aggiornare il riscontro: '+e.message}}));setError(acknowledged?(kind==='submit'?'Risposta salvata':'Operazione salvata')+', ma non è stato possibile aggiornare il riscontro: '+e.message:'Non salvato sul disco: '+e.message+'. La bozza locale è conservata.');return null;}
  }
  useEffect(()=>{if(!view)return;const prefix=`studio-pending:${view.session.id}:`;const keys=Object.keys(localStorage).filter(k=>k.startsWith(prefix));for(const k of keys){const event=JSON.parse(localStorage.getItem(k)!);saving.current=saving.current.catch(()=>{}).then(()=>api(`/sessions/${view.session.id}/events`,event)).then(()=>localStorage.removeItem(k)).catch(e=>setError(e.message));}},[view?.session.id]);
  async function chat(text:string,sessionId?:string,automatic=false,reviewId?:string){
    const sid=sessionId??view?.session.id;if(!sid||!text.trim())return;
    let reviewText='',reviewError='';
    if(reviewId)setReviews(current=>({...current,[reviewId]:{status:'pending'}}));
    await work(async()=>{
      await saving.current;
      if(!automatic){setDraft(current=>current===text?'':current);const stored=sessionStorage.getItem('studio-chat:'+sid);if(!stored||stored===text)sessionStorage.removeItem('studio-chat:'+sid);sessionStorage.setItem('studio-chat-pending:'+sid,text);}
      setStream('');setStatus(reviewId?'Il tutor sta correggendo la risposta…':'Il tutor sta preparando la risposta…');
      const response=await fetch(`/api/sessions/${sid}/chat`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text,automatic,attemptId:reviewId})});
      if(!response.ok)throw Error((await response.json()).error);
      const reader=response.body!.getReader(),decoder=new TextDecoder();let buffer='';
      while(true){
        const {done,value}=await reader.read();if(done)break;
        buffer+=decoder.decode(value,{stream:true});const packets=buffer.split('\n\n');buffer=packets.pop()??'';
        for(const packet of packets){
          if(!packet.startsWith('data: '))continue;const event=JSON.parse(packet.slice(6));
          if(event.type==='delta'){
            setStream(s=>s+event.text);
            if(reviewId){reviewText+=event.text;setReviews(current=>({...current,[reviewId]:{status:'pending',text:reviewText}}));}
          }
          if(event.view)setView(event.view);
          if(event.type==='error'){setError(friendlyReviewError(event.error));reviewError=event.error;}
        }
      }
      setStream('');await refresh(sid);
      if(reviewId)setReviews(current=>({...current,[reviewId]:{status:reviewError?'error':'done',text:reviewText,error:reviewError}}));
      if(!automatic)sessionStorage.removeItem('studio-chat-pending:'+sid);
    },reviewId?message=>{setError(friendlyReviewError(message));setReviews(current=>({...current,[reviewId]:{status:'error',text:reviewText,error:message}}));}:undefined);
    if(!automatic&&sessionStorage.getItem('studio-chat-pending:'+sid)&&!sessionStorage.getItem('studio-chat:'+sid)){setDraft(text);sessionStorage.setItem('studio-chat:'+sid,text);}
  }
  async function assessAttempt(attemptId:string,sessionId?:string){
    const sid=sessionId??viewRef.current?.session.id;if(!sid)return;
    setReviews(current=>({...current,[attemptId]:{status:'pending'}}));
    await work(async()=>{setStatus('Il tutor sta correggendo la risposta…');await saving.current;await api(`/sessions/${sid}/assess`,{attempt_id:attemptId});await refresh(sid);setReviews(current=>({...current,[attemptId]:{status:'done'}}));},message=>setReviews(current=>({...current,[attemptId]:{status:'error',error:message}})));
  }
  const timeline:any[]=[...(view?.messages??[]).filter(m=>m.role!=='system').map(m=>({id:m.id,role:m.role,created:m.created,content:[{type:'text',text:m.text}]})),...(view?.activities??[]).filter(a=>!inCourse||!a.spec.curriculum).map(a=>({id:'activity:'+a.id+':'+a.version,role:'assistant',created:a.created??'',content:[{type:'tool-call',toolCallId:a.id+':'+a.version,toolName:'study_activity',args:{id:a.id,version:a.version},argsText:JSON.stringify({id:a.id,version:a.version}),result:{ready:true}}]}))].sort((a,b)=>a.created.localeCompare(b.created));
  if(stream)timeline.push({id:'stream',role:'assistant',content:[{type:'text',text:stream}]});
  const runtime=useExternalStoreRuntime({convertMessage:(message:any)=>message,messages:timeline,isRunning:busy,onNew:async(message:any)=>{const text=message.content.filter((p:any)=>p.type==='text').map((p:any)=>p.text).join('\n');await chat(text);},onCancel:async()=>{if(view)await api(`/sessions/${view.session.id}/cancel`,{});}});

  async function openSource(id:string){if(!view)return;try{setSource(await api(`/sessions/${view.session.id}/sources/${encodeURIComponent(id)}`));setSourceRequest(v=>v+1);}catch(e:any){setError(e.message);}}
  async function next(){if(!view)return;if(view.learning){if(view.learning.at_end){await chat('Il percorso delle lezioni disponibili è arrivato all’ultimo riepilogo. Aiutami a distinguere argomenti affrontati, lacune nei miei tentativi e prove autonome ancora da fare. Non dichiarare padronanza dal solo avanzamento.');return;}await beginnerAction('advance');return;}if(current?.spec.grading_origin==='generated'){await chat('Proponi il prossimo passo in base al mio ultimo tentativo e alle fonti, usando una nuova attività.');return;}await work(async()=>{await saving.current;setView(await api(`/sessions/${view.session.id}/next`,{}));});}
  const due=view?.progress.filter(p=>p.due&&new Date(p.due)<=new Date())??[];
  function renderActivity(id:string,version:number){
    if(!view)return null;const item=view.activities.find(a=>a.id===id&&a.version===version);if(!item)return null;
    if(current?.id===id&&current.version===version&&!expanded)return <ActivityCard key={current.id+':'+current.version} activity={current} view={view} onEvent={(kind,payload)=>sendEventFor(current,kind,payload,view.session.id)} onNext={()=>void next()} busy={busy} expanded={expanded} setExpanded={setExpanded} onAssess={id=>void assessAttempt(id)} onCorrect={(id,text)=>void work(async()=>{await api(`/sessions/${view.session.id}/correct`,{attempt_id:id,text});await refresh(view.session.id);})}/>;
    return <button className="activity-preview" onClick={()=>void work(async()=>{setView(await api(`/sessions/${view.session.id}/select`,{aid:id,version}));setExpanded(true);})}><span className="eyebrow">ATTIVITÀ · VERSIONE {version}</span><strong>{item.spec.title}</strong><span>Apri ↗</span></button>;
  }
  return <ResumeExplanation.Provider value={id=>void chat('Completa la spiegazione della valutazione già salvata per il tentativo '+id+'. Non ripetere la valutazione né le annotazioni precedenti.',undefined,true,id)}><Reviews.Provider value={reviews}><Tutor.Provider value={()=>setTutorRequest(v=>v+1)}><Sources.Provider value={id=>void openSource(id)}><ActivityRendering.Provider value={renderActivity}><AssistantRuntimeProvider runtime={runtime}><div className="shell">
    <aside className="rail"><a className="brand" href="/" aria-label="Trama home"><span className="brand-mark">t.</span><span>Trama<span className="brand-sub">DALLE TUE FONTI</span></span></a><label className="course-label">IL TUO CORSO<select value={course} onChange={e=>{setCourse(e.target.value);setView(null);setSource(null);}}>{boot?.courses.map((c:any)=><option key={c.id} value={c.id}>{c.label}</option>)}</select></label><nav aria-label="Sezioni">{[['corso','▤','Studia'],['percorso','≡','Percorso'],['allenamento','↻','Allenamento'],['fonti','↗','Fonti']].map(([id,icon,label])=><button key={id} aria-label={label} className={tab===id?'active':''} onClick={()=>setTab(id)}><span>{icon}</span>{label}{id==='allenamento'&&due.length>0&&<span className="count">{due.length}</span>}</button>)}</nav><div className="rail-bottom"><button onClick={()=>setModels(true)}>◇ Modello e accesso</button><span className="quiet">Il tuo archivio, sul tuo Mac.</span></div></aside>
    <main><header className="topbar"><span>{view?.session.mode==='exam'?'Simulazione autonoma':tab==='corso'?'Una cosa alla volta. Il tuo punto è salvato.':tab==='percorso'?'Obiettivo, capitoli e fonti del tuo esame':tab==='allenamento'?'Metti alla prova quello che hai studiato':tab==='studio'?'Il tuo spazio per capire':tab==='programma'?'Dove sei, cosa manca':tab==='ripassi'?'Ritrova quello che sai':'Torna alle fonti'}</span><div className="topbar-actions"><span className="local-indicator">● Salvato sul tuo Mac</span><details className="global-settings" onKeyDown={e=>{if(e.key==='Escape'){e.currentTarget.removeAttribute('open');e.currentTarget.querySelector('summary')?.focus();}}}><summary>Impostazioni</summary><div onClick={e=>{if((e.target as HTMLElement).closest('button'))e.currentTarget.parentElement?.removeAttribute('open');}}><button onClick={()=>setModels(true)}>Modello e accesso</button><button onClick={()=>setTab('sessioni')}>Conversazioni precedenti</button>{!inCourse&&<><button onClick={()=>setTab('programma')}>Programma delle sessioni precedenti</button><button onClick={()=>setTab('ripassi')}>Ripassi delle sessioni precedenti</button></>}<button disabled={busy||!course} onClick={()=>void open()}>Chat libera</button><button disabled={busy||!course} onClick={()=>void startBasics()}>Percorso dalle basi</button><MathReadingSettings/><ThemeToggle/></div></details></div></header>
    {error&&<div className="error-banner" role="alert"><span>{error}</span><button onClick={()=>setError('')} aria-label="Chiudi messaggio">×</button></div>}
    {inCourse?<CourseStudio key={navigationEpoch} mode={tab==='percorso'?'path':tab==='allenamento'?'training':'study'} onMode={mode=>setTab(mode==='path'?'percorso':mode==='training'?'allenamento':'corso')} tutorRequest={tutorRequest} sourceId={source?source.id+':'+sourceRequest:undefined} sourcePanel={source&&view?<SourcePanel embedded key={source.id} source={source} sid={view.session.id} onClose={()=>setSource(null)}/>:null} history={<SessionHistory course={course} busy={busy} onResume={sid=>void work(async()=>{await saving.current;const resumed=await api('/sessions/'+sid+'/resume',{});setView(resumed);setSource(null);if(resumed.curriculum){localStorage.setItem('studio-course-path:'+course,resumed.curriculum.path);await api('/paths/'+resumed.curriculum.path+'/open',{sid});setNavigationEpoch(v=>v+1);setTab('corso');}else setTab('studio');})}/>}  onCancel={async()=>{if(view)await api(`/sessions/${view.session.id}/cancel`,{});}} beforeNavigate={async()=>{window.dispatchEvent(new Event('studio-flush-drafts'));await saving.current;}} messages={<ThreadPrimitive.Messages components={{UserMessage,AssistantMessage}}/>} course={course} view={view} busy={busy} status={status} onSession={v=>{setView(v);if(v.curriculum?.recall)setSource(null);}} onChat={(text,automatic)=>chat(text,undefined,automatic)} onSource={id=>void openSource(id)} onSimulation={v=>{setView(v);setSource(null);setTab('studio');}} renderProse={text=><Prose text={text}/>} renderActivity={(id,version)=>{const a=view?.activities.find(a=>a.id===id&&(version===undefined||a.version===version));return a?<ActivityCard key={a.id+':'+a.version} activity={a} view={view!} onEvent={async(kind,payload)=>{const result=await sendEventFor(a,kind,payload,view!.session.id);if(kind==='submit'&&result?.attempt&&!result.duplicate)void assessAttempt(result.attempt.id,view!.session.id);return result;}} onNext={()=>{const card=document.querySelector<HTMLElement>('[data-activity-id="'+CSS.escape(a.id)+'"]');const block=card?.closest('[data-course-block]');const next=block?.nextElementSibling as HTMLElement|null;if(next)next.scrollIntoView({block:'start',behavior:'instant'});}} busy={busy} expanded={courseExpanded===id} setExpanded={expanded=>setCourseExpanded(expanded?id:null)} onAssess={id=>void assessAttempt(id)} onCorrect={(id,text)=>void work(async()=>{await api(`/sessions/${view!.session.id}/correct`,{attempt_id:id,text});await refresh(view!.session.id);})}/>:null;}}/>:tab==='sessioni'?<SessionHistory course={course} busy={busy} onResume={sid=>void work(async()=>{await saving.current;const resumed=await api('/sessions/'+sid+'/resume',{});setView(resumed);if(resumed.curriculum){localStorage.setItem('studio-course-path:'+resumed.session.course,resumed.curriculum.path);await api('/paths/'+resumed.curriculum.path+'/open',{sid});setTab('corso');}else setTab('studio');setSource(null);setExpanded(false);})}/>:!view?<section className="welcome"><span className="eyebrow">UNA COSA ALLA VOLTA</span><h1>Capire. Provare.<br/><em>Saperlo rifare.</em></h1><p>Riprendi da dove eri rimasto. Il tutor collega le spiegazioni alle tue lezioni e ti aiuta a mettere alla prova il ragionamento.</p>{recommendation&&<p className="recommendation"><strong>Proposto: {recommendation.label}</strong><br/>{recommendation.reason}</p>}<div className="session-options"><label>Tempo disponibile<select value={minutes} onChange={e=>setMinutes(Number(e.target.value))}>{[15,25,45,60].map(n=><option key={n} value={n}>{n} minuti</option>)}</select></label><label>Oggi voglio<input value={goal} onChange={e=>setGoal(e.target.value)}/></label></div><button className="primary large basics-start" disabled={!course||busy} onClick={()=>setTab('corso')}>Crea o riprendi il piano del corso →</button><button className="primary large" disabled={!course||busy} onClick={()=>void open()}>Riprendi il percorso <span>→</span></button><button className="primary large basics-start" disabled={!course||busy} onClick={()=>void startBasics()}>Parti dalle basi</button><p className="quiet">Prerequisiti, spiegazioni ed esempi nell’ordine delle tue lezioni.</p><button className="text-button" disabled={!course||busy} onClick={()=>void open('learn',true)}>Inizia una nuova sessione</button><p className="quiet" role="status">{status||(!boot?'Apro il tuo archivio…':!boot.courses.length?'Aggiungi i materiali di un corso per iniziare con Trama.':'Fonti originali e progressi restano nel tuo archivio.')}</p></section>:<>
    {tab==='studio'&&view.learning&&<section className="beginner-path" aria-label="Percorso dalle basi"><div><span className="eyebrow">DALLE BASI · LE TUE LEZIONI</span><label>Lezione<select aria-label="Lezione" value={view.learning.lesson?.id??''} disabled={busy} onChange={e=>void beginnerAction('lesson',{lesson:e.target.value})}>{view.learning.lessons.map((l:any)=><option key={l.id} value={l.id}>{l.order}. {l.label}</option>)}</select></label><p className="quiet">{view.learning.lesson?.quality}</p></div><div><strong>{view.learning.current_unit?.title??'Ricavo gli argomenti dalle fonti della lezione'}</strong><p>{view.learning.phase_label}{view.learning.units.length?' · argomento '+(view.learning.unit_index+1)+' di '+view.learning.units.length:''}</p><p className="quiet">{view.learning.current_unit?.objective??'Il tutor legge trascrizione e materiali prima di proporre il percorso.'}</p><button disabled={busy} onClick={()=>void chat('Riprendi la fase corrente del percorso dalle basi, usando le fonti della lezione e spiegando un concetto alla volta.')}>Riprendi la spiegazione</button><button disabled={busy} onClick={()=>void next()}>{view.learning.at_end?'Rivedi i punti da chiarire':'Prossimo passo →'}</button><details><summary>Argomenti della lezione</summary><label>Argomento<select aria-label="Argomento" value={view.learning.unit_index} disabled={busy||!view.learning.units.length} onChange={e=>void beginnerAction('unit',{unit:Number(e.target.value)})}>{view.learning.units.map((u:any,i:number)=><option key={u.id} value={i}>{i+1}. {u.title}</option>)}</select></label>{view.learning.units.map((u:any,i:number)=><p key={u.id}><strong>{i+1}. {u.title}</strong><br/>{u.objective}<br/><span className="quiet">Prerequisiti: {u.prerequisites.join(', ')||'Nessuno dichiarato'}</span></p>)}</details><span className="quiet">Avanzare nel percorso non certifica la comprensione.</span></div></section>}{tab==='studio'&&<div className={'study-layout '+(expanded?'focus':'inline')}><section className="conversation"><div className="conversation-heading"><span className="eyebrow">{view.session.goal}</span><h1>Impariamo facendo.</h1><details className="session-settings"><summary>{minutes} minuti · modifica obiettivo</summary><label>Tempo<select value={minutes} onChange={e=>setMinutes(Number(e.target.value))}>{[15,25,45,60].map(n=><option key={n} value={n}>{n} minuti</option>)}</select></label><label>Obiettivo<input value={goal} onChange={e=>setGoal(e.target.value)}/></label><button onClick={()=>void work(async()=>setView(await api(`/sessions/${view.session.id}/preferences`,{goal,minutes})))}>Salva preferenze</button></details></div><ThreadPrimitive.Root className="thread"><ThreadPrimitive.Viewport className="messages" autoScroll={false}><ThreadPrimitive.Messages components={{UserMessage,AssistantMessage}}/></ThreadPrimitive.Viewport></ThreadPrimitive.Root>{busy&&<p className="quiet" role="status">{status||'Operazione in corso…'}</p>}<form className="composer" onSubmit={e=>{e.preventDefault();if(!busy&&draft.trim()&&view.session.mode!=='exam')void chat(draft);}}><label className="sr-only" htmlFor="chat-input">Messaggio al tutor</label><textarea id="chat-input" rows={3} value={draft} aria-describedby="chat-shortcuts" onKeyDown={e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.nativeEvent.isComposing&&e.nativeEvent.keyCode!==229){e.preventDefault();if(!e.repeat&&!busy&&draft.trim()&&view.session.mode!=='exam')e.currentTarget.form?.requestSubmit();}}} onChange={e=>{setDraft(e.target.value);sessionStorage.setItem('studio-chat:'+view.session.id,e.target.value);}} placeholder={view.session.mode==='exam'?'Durante la prova, usa il campo di risposta.':'Chiedi, ragiona ad alta voce o cambia argomento…'} disabled={view.session.mode==='exam'}/><div><span className="quiet" id="chat-shortcuts">Invio invia · Shift+Invio va a capo.</span>{busy?<button type="button" onClick={()=>void api(`/sessions/${view.session.id}/cancel`,{})}>Interrompi</button>:<button type="submit" className="send" disabled={!draft.trim()||view.session.mode==='exam'} aria-label="Invia messaggio">↑</button>}</div></form><div className="session-links">{!view.learning&&<button disabled={busy} onClick={()=>void startBasics()}>Parti dalle basi</button>}<button disabled={busy} onClick={()=>void open('learn',true)}>Nuova sessione</button><button onClick={()=>void open(view.session.mode==='exam'?'learn':'exam',view.session.mode!=='exam')}>{view.session.mode==='exam'?'Torna allo studio':'Simulazione autonoma'}</button></div></section>{current&&expanded&&<ActivityCard key={current.id+':'+current.version} activity={current} view={view} onEvent={(kind,payload)=>sendEventFor(current,kind,payload,view.session.id)} onNext={()=>void next()} busy={busy} expanded={expanded} setExpanded={setExpanded} onAssess={id=>void assessAttempt(id)} onCorrect={(id,text)=>void work(async()=>{await api(`/sessions/${view.session.id}/correct`,{attempt_id:id,text});await refresh(view.session.id);})}/>}</div>}
    {tab==='programma'&&<section className="overview"><span className="eyebrow">EVIDENZE, NON UN VOTO PREVISTO</span><h1>Il tuo percorso</h1><p>Le competenze si confermano con tentativi autonomi e problemi diversi, anche a distanza.</p>{view.learning?view.learning.lessons.map((l:any)=><article className="concept" key={l.id}><div><h3>{l.order}. {l.label}</h3><span className="quiet">{l.quality}</span></div><button disabled={busy} onClick={()=>void beginnerAction('lesson',{lesson:l.id})}>Studia questa lezione →</button></article>):view.progress.map(p=><article className="concept" key={p.id}><div><h3>{p.label}</h3><span className="quiet">{p.attempts} tentativi · {p.prerequisites.length?'Prerequisiti: '+p.prerequisites.join(', '):'Nessun prerequisito registrato'}</span></div><span className="tag">{p.status}</span><button onClick={()=>{setTab('studio');void chat('Vorrei studiare '+p.label+'. Cerca le fonti e proponi il prossimo passo.');}}>Studia →</button></article>)}</section>}
    {tab==='ripassi'&&<section className="overview"><span className="eyebrow">RICORDA SENZA GUARDARE</span><h1>Ripassi</h1>{view.learning?.recalls.map((r:any)=><article className="concept" key={r.lesson+':'+r.unit}><div><h3>{r.title} · richiamo dal percorso</h3><span className="quiet">{r.lesson_label}</span><p className="quiet">Proposto dal {new Date(r.due).toLocaleString('it-IT')} · da un tentativo autonomo, con valutazione provvisoria</p></div><button disabled={busy} onClick={()=>void beginnerAction('recall',{lesson:r.lesson,unit:r.unit})}>Riprendi il richiamo</button></article>)}<p>{due.length?`${due.length} richiami da riprendere.`:'Nessun richiamo scaduto. Puoi continuare il percorso.'}</p>{view.progress.filter(p=>p.due).map(p=><article className="concept" key={p.id}><div><h3>{p.label}</h3><span className="quiet">Prossimo richiamo: {new Date(p.due).toLocaleString('it-IT')}</span></div><button onClick={()=>void work(async()=>{await saving.current;setView(await api(`/sessions/${view.session.id}/recall`,{concept:p.id}));setTab('studio');})}>Mettimi alla prova →</button></article>)}</section>}
    {tab==='fonti'&&<section className="overview"><span className="eyebrow">IL CORSO, CON I RIFERIMENTI</span><h1>Fonti</h1><IndexStatus course={course}/><form className="search" onSubmit={e=>{e.preventDefault();void work(async()=>setResults(await api(`/sessions/${view.session.id}/search?q=${encodeURIComponent(query)}`)));}}><label className="sr-only" htmlFor="search-input">Cerca nelle fonti</label><input id="search-input" value={query} onChange={e=>setQuery(e.target.value)} placeholder="Un concetto, una formula, un passaggio…"/><button className="primary" disabled={busy}>Cerca</button></form>{results.map(r=><button className="search-result" key={r.id} onClick={()=>void openSource(r.id)}><span className="eyebrow">{r.kind} · {r.quality}</span><h3>{r.title}{r.page!=null?' · '+(r.kind==='notebook'?'cella ':'pagina ')+r.page:''}</h3><p>{r.text.slice(0,350)}…</p>{r.metadata?.issue&&<span className="notice">{r.metadata.issue}</span>}</button>)}<MaterialsLibrary key={view.session.id} sid={view.session.id} onSource={id=>void openSource(id)}/></section>}
    </>}
    </main>{source&&view&&!inCourse&&<SourcePanel key={source.id} source={source} sid={view.session.id} onClose={()=>setSource(null)}/>} {models&&<ModelPanel onClose={()=>setModels(false)} onSaved={()=>void bootstrap()}/>}</div></AssistantRuntimeProvider></ActivityRendering.Provider></Sources.Provider></Tutor.Provider></Reviews.Provider></ResumeExplanation.Provider>;
}
createRoot(document.getElementById('root')!).render(<MathReadingProvider><App/></MathReadingProvider>);
